import { Component, HostBinding, OnInit } from '@angular/core';
import { ActivatedRoute, Router } from '@angular/router';

import { NavController, Platform } from '@ionic/angular';
import { routeAnimation } from '../../shared';
import { HttpClientService } from '../../shared/http-client.service';
import { isNotNullOrUndefined } from 'codelyzer/util/isNotNullOrUndefined';
import { Key } from 'protractor';
import { debug } from 'console';
import {environment} from "../../../environments/environment";

@Component({
    selector: 'app-select-census-address',
    templateUrl: 'select-census-address.page.html',
    styleUrls: ['select-census-address.page.scss'],
    animations: [    // 路由动画
        routeAnimation
    ]
})
export class SelectCensusAddressPage implements OnInit {
    addressList = [];
    /**
     * 存储初始化的所有采集点信息
     */
    addressAllList = [];
    censusAddress = {
        address: undefined,
        contact: undefined,
        contactNumber: undefined,
        description: undefined,
        id: 0,
        lat: undefined,
        lng: undefined,
        mapName: undefined
    };
    address;
    censusId;
    addressInput = '';
    AllAddressList = [];
    load;
    constructor(
        private router: Router,
        public navCtrl: NavController,
        private http: HttpClientService,
        private route: ActivatedRoute,
        private platform: Platform
    ) {
        // 控制app返回按钮
        this.platform.backButton.subscribeWithPriority(10, () => {
            this.routeBack();
        });
    }

    @HostBinding('@routeAnimation') state;   // 路由动画
    ngOnInit(): void {
        this.load = document.getElementsByClassName('census-address-load-bar')[0];
    }
    ionViewWillEnter() {
        // 获取采集点
        this.init();
    }
    init() {
        const condition = {
            address: '',
            pageNum: 1,
            pageSize: 50
        };
        this.censusaddress(condition);
    }

    // 路由返回
    routeBack() {
        this.router.navigate(['/login']);
    }


    // 选择对号按钮
    selectCheackRegister(value, item) {
        const str = 'selectAddress' + value;
        const radio = document.getElementsByClassName(str)[0];
        // 清除所有对号
        for (let z = 0; z < this.addressList.length; z++) {
            const radioRem = document.getElementsByClassName('selectAddress' + z)[0];
            radioRem.className = this.removeClass(radioRem, 'selectAddresShow');
        }
        // 显示当前对号
        radio.className = radio.className + ' selectAddresShow';
        this.address = (item.area == null || item.area == ''?'': item.area+'-') +
            (item.street == null || item.street == ''?'': item.street+'-') +item.address;
        this.censusId = item.id;
    }
    removeClass(dom, clzName) {
        let clzNewName = dom['className'];
        let classname = '';
        if (clzNewName && clzNewName.length > 0) {
            clzNewName = clzNewName.split(' ');
            for (let i = clzNewName.length; i--;) {
                if (clzNewName[i] === clzName) {
                    clzNewName.splice(i, 1);
                    classname = clzNewName.join(' ');
                    return classname;
                }
            }
        }
        return clzNewName.join(' ');
    }
    search() {
        // this.addressList = this.AllAddressList.filter( w => w['address'].indexOf(this.addressInput) > -1);
        this.address = '';
        const condition = {
            address: this.addressInput,
            pageNum: 1,
            pageSize: 50
        };
        this.censusaddress(condition);
    }
    /**
     * 
     * @param value 实时过滤搜索显示匹配的采集点
     */
    searchRealTime(KeyEvent) {
        // if (KeyEvent.code === 'Space' || KeyEvent.code === 'Enter' || KeyEvent.code === 'Backspace' || KeyEvent.code === 'Delete') {
        let txtAdd = this.addressInput.trim();
        let tmpAddressList = [];
        if (this.addressAllList !== undefined && this.addressAllList.length > 0) {
            for (const keyAddr of this.addressAllList) {
                if (keyAddr['address'].includes(txtAdd)) {
                    tmpAddressList.push(keyAddr);
                }
            }
        }
        // 因为后台每次只返回50条记录，所以需要到数据库中再次查询，才准确
        let isSearch: boolean = false;
        if (txtAdd.length > 0) {
            let tmpAdd = txtAdd.substring(txtAdd.length - 1);
            let numTmpCHN = this.GetCHNum(tmpAdd);
            if (numTmpCHN > 0) {
                isSearch = true;
            }
        }
        // 如果最后输入的是汉字，则到数据库中查询
        if (isSearch) {
            this.search();
        }
        else {
            this.addressList = this.addressAllList;
        }
        // }
    }
    /**
     * 
     * @param value 获取字符串中的汉字数量
     */
    GetCHNum(value) {
        let num = 0;
        for (var i = 0; i < value.length; i++) {
            if ((value.charCodeAt(i) < 0) || (value.charCodeAt(i) > 255)) {
                num += 1;
            }
        }

        return num;
    }

    okButton() {
        sessionStorage.setItem('censusAddress', this.address);
        if (isNotNullOrUndefined(this.address) && this.address !== '') {
            this.saveCensusAddress();
        } else {
            this.http.showToast('采集点为空，请选择采集点！');
        }
    }
    // 调用后台接口
    // 获取采集点
    censusaddress(condition) {
        this.addressList = [];
        this.censusAddress = {
            address: undefined,
            contact: undefined,
            contactNumber: undefined,
            description: undefined,
            id: 0,
            lat: undefined,
            lng: undefined,
            mapName: undefined
        };
        this.load['style']['display'] = 'inline-block';
        this.http
            .post(`rcp/api/censusaddress/select`, condition, '获取采集点', environment.FailMessage.getCensusAddress)
            .subscribe(data => {
                this.load['style']['display'] = 'none';
                if (data['isSuccess']) {
                    this.addressList = data['data'];
                    if (data['data'].length > this.addressAllList.length) {
                        this.addressAllList = data['data'];
                    }
                }
            });
    }

    saveCensusAddress() {
        const censusAddress = {
            censusId: this.censusId,
        };
        this.load['style']['display'] = 'inline-block';
        this.http
            .post(`rcp/api/user/census/address` + this.http.getParamsString(censusAddress), {},
                '保存采集点', environment.FailMessage.saveCensusAddress)
            .subscribe(data => {
                this.load['style']['display'] = 'none';
                if (data['isSuccess']) {
                    this.router.navigate(['/tabs/tab1']);
                }
            });
    }
}
